window.AUTH=window.AUTH||{};window.AUTH["19-783"]={"d":"19-783","id":"2020/19-783","n":"Van Buren v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Nathan Van Buren","date":"2020-07-01","url":"https://www.supremecourt.gov/DocketPDF/19/19-783/146727/20200701130402295_19-783BriefForPetitioner.pdf","side":"pet","n":101},{"k":"united-states","label":"Brief amicus curiae of The United States Technology Policy Committee of the ACM in support of neither party","date":"2020-07-08","url":"https://www.supremecourt.gov/DocketPDF/19/19-783/147196/20200708104631325_Amicus%20Brief.pdf","side":"us","n":26},{"k":"respondent","label":"Brief of respondent United States","date":"2020-08-27","url":"https://www.supremecourt.gov/DocketPDF/19/19-783/151518/20200827161906264_19-783bsUnitedStates.pdf","side":"res","n":86},{"k":"reply","label":"Reply of petitioner Nathan Van Buren","date":"2020-09-28","url":"https://www.supremecourt.gov/DocketPDF/19/19-783/155055/20200928114834562_19-783ReplyBriefForPetitioner.pdf","side":"pet","n":45}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/593us2r42_n7ip.pdf","tr":true,"items":[{"t":"case","label":"Applied Gen. Agency, Inc. v. Greenleaf Fin. & Ins. Servs., Inc.","cite":"2019 WL 5255271","y":2019,"court":"Cal. Ct. App. Oct. 17","by":{"0":"25"}},{"t":"case","label":"Arthur Andersen LLP v. United States","cite":"544 U.S. 696","y":2005,"id":"2004/04-368","sc":1,"sum":"The Court held that the jury instructions failed to convey that the federal document law required a \"consciousness of wrongdoing\" for conviction. There was nothing inherently corrupt in ordering employees to destroy documents, even if the aim was to keep the documents from the government.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Barton v. Barr","cite":"140 S. Ct. 1442","y":2020,"id":"2019/18-725","sc":1,"sum":"The Court held that in determining eligibility for cancellation of removal of a lawful permanent resident who commits a serious crime, an offense listed in 8 U.S.C. § 1182(a)(2) committed during the initial seven years of residence need not be one of the offenses of removal.","sumSrc":"Oyez","by":{"0":"20","3":"5"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"op":1,"ar":1,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"0":"1, 26, 29, 31","2":"20","3":"6, 7"}},{"t":"case","label":"Brand Energy & Infrastructure Servs., Inc. v. Irex Contracting Grp.","cite":"2017 WL 1105648","y":2017,"court":"E.D. Pa. Mar. 24","by":{"0":"9"}},{"t":"case","label":"Branzburg v. Hayes","cite":"408 U.S. 665","y":1972,"id":"1971/70-85","sc":1,"sum":"The Court held that requiring reporters to testify before a grand jury does not violate freedom of press or speech in the First Amendment.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Burgess v. United States","cite":"553 U.S. 124","y":2008,"id":"2007/06-11429","sc":1,"sum":"The Court upheld the sentencing hike, stating that the definition of a felony drug offense in 12 U.S.C. 841 as punishable by imprisonment for more than one year was controlling regardless of whether South Carolina classified the offense as a felony or a misdemeanor.","sumSrc":"Oyez","by":{"0":"20, 22"}},{"t":"case","label":"Cent. Bank & Tr. v. Smith","cite":"215 F. Supp. 3d 1226","y":2016,"court":"D. Wyo.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/215/1226/","by":{"0":"9"}},{"t":"case","label":"Chickasaw Nation v. United States","cite":"534 U.S. 84","y":2001,"id":"2001/00-507","sc":1,"sum":"The Court held that Indian Regulatory Gaming Act does not create such an exemption. The Court reasoned that despite its parenthetical reference, the language outside the parenthetical was unambiguous and the subsection applied only to Internal Revenue Code provisions that concerned the reporting and withholding of taxes.","sumSrc":"Oyez","by":{"0":"21","3":"8"}},{"t":"case","label":"Christopher v. SmithKline Beecham Corp.","cite":"567 U.S. 142","y":2012,"id":"2011/11-204","sc":1,"sum":"The Court held that the Secretary of Labor's definition of \"outside salesman\" apply to pharmaceutical sales representatives under the Fair Labor Standards Act.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"0":"34, 36","2":"44","3":"20"}},{"t":"case","label":"Cleveland v. United States","cite":"531 U.S. 12","y":2000,"id":"2000/99-804","sc":1,"sum":"The Court held that State and municipal licenses in general, and Louisiana's video poker licenses in particular, do not rank as \"property,\" for purposes of federal law, in the hands of the official licensor.","sumSrc":"Oyez","by":{"0":"1, 26, 29, 40","3":"5, 6"}},{"t":"case","label":"Cloudpath Networks, Inc. v. SecureW2 B.V.","cite":"157 F. Supp. 3d 961","y":2016,"court":"D. Colo.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/157/961/","by":{"0":"9"}},{"t":"case","label":"County of Maui v. Hawaii Wildlife Fund","cite":"140 S. Ct. 1462","y":2020,"id":"2019/18-260","sc":1,"sum":"The Court held the Clean Water Act requires a permit when pollutants originate from a point source but are conveyed to navigable waters by a nonpoint source, such as groundwater, if the conveyance is the \"functional equivalent\" of a direct discharge.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Crabar/GBF, Inc. v. Wright","cite":"2019 WL 4016122","y":2019,"court":"D. Neb. Aug. 26","by":{"0":"9"}},{"t":"case","label":"Cvent, Inc. v. Eventbrite, Inc.","cite":"739 F. Supp. 2d 927","y":2010,"court":"E.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/739/927/","by":{"0":"35","2":"37"}},{"t":"case","label":"Dresser–Rand Co. v. Jones","cite":"957 F. Supp. 2d 610","y":2013,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/957/610/","by":{"0":"9"}},{"t":"case","label":"Econ. Research Servs., Inc. v. Resolution Econ., LLC","cite":"208 F. Supp. 3d 219","y":2016,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/208/219/","by":{"0":"9"}},{"t":"case","label":"EF Cultural Travel BV v. Explorica, Inc.","cite":"274 F.3d 577","y":2001,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/274/577/","op":1,"by":{"0":"7"}},{"t":"case","label":"Erlich Prot. Sys., Inc. v. Flint","cite":"2019 WL 5851938","y":2019,"court":"Mich. Ct. App. Nov. 7","by":{"0":"25"}},{"t":"case","label":"Experian Mktg. Sols., Inc. v. Lehman","cite":"2015 WL 5714541","y":2015,"court":"W.D. Mich. Sept. 29","by":{"0":"10"}},{"t":"case","label":"FCC v. Fox Television Stations, Inc.","cite":"556 U.S. 502","y":2009,"id":"2008/07-582","sc":1,"sum":"The Court held that the FCC's imposition of liability on Fox Television Stations for fleeting expletives was not \"arbitrary and capricious\" under the Administrative Procedure Act, even though the FCC previously accepted similar expletives.","sumSrc":"Oyez","by":{"0":"36","3":"20"}},{"t":"case","label":"Florida Star v. B.J.F.","cite":"491 U.S. 524","y":1989,"id":"1988/87-329","sc":1,"sum":"The Supreme Court held that the civil damages imposed on Florida Star violated the First Amendment because the information was lawfully-obtained and truthful. The Court hinted that there may be a situation where a victim’s privacy interest outweighed a newspaper’s First Amendment rights.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Fox v. Standard Oil Co.","cite":"294 U.S. 87","y":1935,"id":"scdb/1934-085","sc":1,"sum":"1. Filling stations and distribution plants where gasoline, other petroleum products, and automobile accessories are sold, are \"stores \" within the meaning of the West Virginia Chain Store License Tax Act, defining the term store as including any mercantile establishment in which goods, wares or merchandise of any kind are sold, etc.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Giles Constr., LLC v. Tooele Inventory Sol., Inc.","cite":"2015 WL 3755863","y":2015,"court":"D. Utah June 16","by":{"0":"9"}},{"t":"case","label":"GPMM, Inc. v. Tharp","cite":"2019 WL 7161229","y":2019,"court":"D. Neb. Oct. 3","by":{"0":"9"}},{"t":"case","label":"Havens Realty Corp. v. Coleman","cite":"455 U.S. 363","y":1982,"id":"1981/80-988","sc":1,"sum":"Section 804 of the Fair Housing Act of 1968 (Act) makes unlawful various forms of discriminatory housing practices. Section 812(a) authorizes civil actions to enforce §804 and requires that suit be brought within 180 days after the alleged occurrence of a discriminatory practice. A class action for declaratory, injunctive, and monetary relief was brought in Federal District Court against petitioners-Havens Realty …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36, 37"}},{"t":"case","label":"Hedgeye Risk Mgmt., LLC v. Heldman","cite":"271 F. Supp. 3d 181","y":2017,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/271/181/","by":{"0":"9"}},{"t":"case","label":"Henson v. Santander Consumer USA, Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Int’l Airport Ctrs., L.L.C. v. Citrin","cite":"440 F.3d 418","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/440/418/","op":1,"by":{"0":"7"}},{"t":"case","label":"Integrated Process Sols., Inc. v. Lanix LLC","cite":"2019 WL 1238835","y":2019,"court":"D. Minn. Mar. 18","by":{"0":"9"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Johnson v. United States","cite":"135 S. Ct. 2551","y":2015,"id":"2014/13-7120","sc":1,"sum":"The Court determined that the residual clause of the Armed Criminal Career Act is unconstitutionally vague.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Kappe Assocs., Inc. v. Chesapeake Environ. Equip., LLC","cite":"2016 WL 1257665","y":2016,"court":"E.D. Pa. Mar. 31","by":{"0":"9"}},{"t":"case","label":"Kelly v. United States","cite":"140 S. Ct. 1565","y":2020,"id":"2019/18-1059","sc":1,"sum":"The Court held that Baroni and Kelly, who executed the New Jersey “Bridgegate” political retribution scheme against Fort Lee’s mayor, did not violate the federal-program fraud or wire fraud laws because they did not aim to obtain money or property from the federal Port Authority.","sumSrc":"Oyez","by":{"0":"1, 29","3":"5, 6"}},{"t":"case","label":"KNC Techs., LLC v. Tutton","cite":"2019 WL 6219035","y":2019,"court":"N.C. Super. Ct. Oct. 9","by":{"0":"25"}},{"t":"case","label":"Kolender v. Lawson","cite":"461 U.S. 352","y":1983,"id":"1982/81-1320","sc":1,"sum":"The law was unconstitutionally vague because it gave excessive discretion to the police (in the absence of probable cause for an arrest) whether to stop and interrogate a suspect or leave him alone. The majority hinted that the California statute compromised the constitutional right to freedom of movement.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Koons v. United States","cite":"138 S. Ct. 1783","y":2018,"id":"2017/17-5716","sc":1,"sum":"The Court decided that the petitioners, who were criminal defendants, were not eligible for sentence reductions under 18 U.S.C. § 3582(c)(2) because their sentences were not “based on” their lowered Federal Sentencing Guidelines ranges, but rather were “based on” the mandatory minimum sentences for their offenses and their substantial assistance to the government.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Lanzetta v. New Jersey","cite":"306 U.S. 451","y":1939,"id":"scdb/1938-099","sc":1,"sum":"repugnant to the due process clause of the Fourteenth Amendment, because of its vaguenes and uncertainty. P. 453. 120 N. J. L. 189; 198 A. 837, reversed. APPEAL from a judgment affirming a conviction and sentence of three men as gangsters. See also 118 N. J. L. 212; 192 A.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"Lee v. PMSI, Inc.","cite":"2011 WL 1742028","y":2011,"court":"M.D. Fla. May 6","by":{"0":"35","2":"42"}},{"t":"case","label":"Liparota v. United States","cite":"471 U.S. 419","y":1985,"id":"1984/84-5108","sc":1,"sum":"Absent any indication of a contrary purpose in the statute's language or legislative history, the Government in a prosecution for violation of § 2024(b)(1) must prove that the defendant knew that his acquisition or possession of food stamps was in a manner unauthorized by statute or regulations.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"Lozman v. City of Riviera Beach","cite":"568 U.S. 115","y":2013,"id":"2012/11-626","sc":1,"sum":"The Court held that the definition of vessel under 1 U.S.C. §3 is too broad and not any floating structure is considered a vessel.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Marinello v. United States","cite":"138 S. Ct. 1101","y":2018,"id":"2017/16-1144","sc":1,"ar":3,"sum":"The Court held that a conviction under 26 U.S.C. § 7212(a) for corruptly endeavoring to obstruct or impede the due administration of the tax laws requires proof that the defendant acted with knowledge of a pending Internal Revenue Service action.","sumSrc":"Oyez","by":{"0":"1, 3, 29, 30, 33","2":"43","3":"6, 12"}},{"t":"case","label":"Mathey Dearman, Inc. v. H&M Pipe Beveling Mach. Co.","cite":"2018 WL 4224897","y":2018,"court":"N.D. Okla. Sept. 5","by":{"0":"9"}},{"t":"case","label":"McDonnell v. United States","cite":"136 S. Ct. 2355","y":2016,"id":"2015/15-474","sc":1,"op":1,"ar":2,"sum":"The Court held that, for the purpose of federal bribery statutes, an “official act” is a decision or action on a question, matter, cause, suit, proceeding, or controversy that involves a specific exercise of formal governmental power.","sumSrc":"Oyez","by":{"0":"1, 3, 29, 34","3":"6"}},{"t":"case","label":"Meese v. Keene","cite":"481 U.S. 465","y":1987,"id":"1986/85-1180","sc":1,"sum":"The Foreign Agents Registration Act of 1938 (Act) requires registration, reporting, and disclosure by persons engaging in propaganda on behalf of foreign powers. The Act uses the term \"political propaganda\" to identify those expressive materials subject to its requirements, and defines the term as, inter alia, any communication intended to influence the United States' foreign policies. Appellee, a member of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Milner v. Dep’t of Navy","cite":"562 U.S. 562","y":2011,"id":"2010/09-1163","sc":1,"sum":"The Court held that documents related to the effect of explosions from Navy exercises did not qualify for withholding under Exception 2 of the Freedom of Information Act.","sumSrc":"Oyez","by":{"0":"21","3":"9"}},{"t":"case","label":"Orbit One Communications, Inc. v. Numerex Corp.","cite":"692 F. Supp. 2d 373","y":2010,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/692/373/","sum":"Construing the CFAA to “encompass an employee’s misuse or misappropriation of information . . . would depart from the plain meaning of the statute”.","sumSrc":"brief:0","by":{"0":"19"}},{"t":"case","label":"Packingham v. North Carolina","cite":"137 S. Ct. 1730","y":2017,"id":"2016/15-1194","sc":1,"sum":"The Court determined that the North Carolina law prohibiting registered sex offenders from accessing various websites, where minors are known to be active and have accounts, regardless of whether or not the sex offender directly interacted with a minor violates the First Amendment.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Roe v. Bernabei & Wachtel PLLC","cite":"85 F. Supp. 3d 89","y":2015,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/85/89/","by":{"0":"9"}},{"t":"case","label":"Sandvig v. Barr","cite":"2020 WL 1494065","y":2020,"court":"D.D.C. Mar. 27","sum":"Finding a credible threat of prosecution under the CFAA for terms-of-service violations in part because of “the absence of a specific disavowal of prosecution by the Department”.","sumSrc":"brief:0","by":{"0":"9, 33, 36, 37","2":"37"}},{"t":"case","label":"Sebrite Agency, Inc. v. Platt","cite":"884 F. Supp. 2d 912","y":2012,"court":"D. Minn.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/884/912/","by":{"0":"9"}},{"t":"case","label":"Shamrock Chi. Corp. v. Wroblewski","cite":"2019 WL 7373359","y":2019,"court":"Ill. Ct. App. Dec. 31","by":{"0":"25"}},{"t":"case","label":"Stenberg v. Carhart","cite":"530 U.S. 914","y":2000,"id":"1999/99-830","sc":1,"sum":"In a complicated 5-4 decision delivered by Justice Stephen G. Breyer, the Court held that \"Nebraska's statute criminalizing the performance of \"partial birth abortion[s]\" violates the U.S. Constitution, as interpreted in Casey and Roe.\" The sharply divided Court struck down the statute because it placed an undue burden on a woman's right to have an abortion and did not allow for exception in cases of threatened health. \"All those who perform abortion procedures using that method must fear prosecution, conviction, and imprisonment,\" that results in \"an undue burden upon a woman's right to make an abortion decision,\" wrote Justice Breyer for the Court.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Tank Connection, LLC v. Haight","cite":"161 F. Supp. 3d 957","y":2016,"court":"D. Kan.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/161/957/","by":{"0":"9"}},{"t":"case","label":"Teva Pharms. USA, Inc. v. Sandhu","cite":"291 F. Supp. 3d 659","y":2018,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/291/659/","by":{"0":"9"}},{"t":"case","label":"TripleTree, LLC v. Walcker","cite":"2016 WL 2621954","y":2016,"court":"D. Minn. May 6","by":{"0":"9"}},{"t":"case","label":"United States v. Alvarez","cite":"567 U.S. 709","y":2012,"id":"2011/11-210","sc":1,"sum":"The Court found that the Stolen Valor Act violated the First Amendment.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"sum":"It is not clear from the language and legislative history of § 1202 (a) (1) whether or not receipt or possession of a firearm by a convicted felon has to be shown in an individual prosecution to have been connected with interstate commerce. The ambiguity of this provision (which is not only a criminal statute but one whose broad construction would define as a federal offense conduct readily proscribed by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40","3":"23"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"40"}},{"t":"case","label":"United States v. Drew","cite":"259 F.R.D. 449","y":2009,"court":"C.D. Cal.","url":"https://www.courtlistener.com/c/F.R.D./259/449/","ar":3,"by":{"0":"32","2":"41"}},{"t":"case","label":"United States v. John","cite":"597 F.3d 263","y":2010,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/597/263/","op":1,"by":{"0":"7 - 8","1":"6","2":"41"}},{"t":"case","label":"United States v. Kozminski","cite":"487 U.S. 931","y":1988,"id":"1987/86-2000","sc":1,"ar":1,"sum":"The Court held that precedent had established that the type of involuntary servitude prohibited by the Thirteenth Amendment is limited to that “enforced by the use or threatened use of physical or legal coercion.” Involuntary servitude had never before been extended to cover labor compelled by the use of psychological coercion.","sumSrc":"Oyez","by":{"0":"30","2":"49","3":"12"}},{"t":"case","label":"United States v. Lowson","cite":"2010 WL 9552416","y":2010,"court":"D.N.J. Oct. 12","by":{"0":"32","2":"41"}},{"t":"case","label":"United States v. Nosal","cite":"676 F.3d 854","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/676/854/","op":1,"ar":1,"by":{"0":"passim","1":"8","3":"1, 15, 24"}},{"t":"case","label":"United States v. R.L.C.","cite":"503 U.S. 291","y":1992,"id":"1991/90-1577","sc":1,"sum":"The judgment is affirmed. 915 F. 2d 320, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"United States v. Rodriguez","cite":"628 F.3d 1258","y":2010,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/628/1258/","op":1,"by":{"0":"passim","2":"12"}},{"t":"case","label":"United States v. Santos","cite":"553 U.S. 507","y":2008,"id":"2007/06-1005","sc":1,"sum":"Splitting 5 to 4, the Court affirmed the Seventh Circuit, answering that \"proceeds\" refers to \"net income\" or profits and not to \"gross income.\" Because the statute nowhere defines the term \"proceeds\", the plurality applied the so-called rule of lenity which requires such ambiguous statutes to be interpreted in favor of defendants.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"United States v. Stevens","cite":"559 U.S. 460","y":2010,"id":"2009/08-769","sc":1,"sum":"The Court ruled that 18 U.S.C. Section 48 was unconstitutional under the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"United States v. Valle","cite":"807 F.3d 508","y":2015,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/807/508/","op":2,"by":{"0":"passim","1":"5","2":"40"}},{"t":"case","label":"United States v. Wheeler","cite":"886 F.3d 415","y":2018,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/886/415/","sum":"Noting the Department of Justice’s “reconsider[ation]” and “change of position” regarding the scope of a criminal statute.","sumSrc":"brief:0","by":{"0":"34"}},{"t":"case","label":"United States v. Wiltberger","cite":"18 U.S. 76","y":1820,"id":"scdb/1820-003","sc":1,"sum":"The United States v. Wiltberger.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"Viking Grp., Inc. v. Bruckman","cite":"2020 WL 2296903","y":2020,"court":"Mich. Ct. App. May 7","by":{"0":"25"}},{"t":"case","label":"WEC Carolina Energy Sols. LLC v. Miller","cite":"687 F.3d 199","y":2012,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/687/199/","op":1,"by":{"0":"9"}},{"t":"case","label":"Western Union Telegraph Co. v. Lenroot","cite":"323 U.S. 490","y":1945,"id":"scdb/1944-127","sc":1,"sum":"1. The legislative history of the child labor provisions of the Fair Labor Standards Act of 1938 is inconclusive as to whether the Act was intended to reach such child labor as is here involved.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"ix Wyndham Vacation Ownership, Inc. v. Miloszewski","cite":"2014 WL 5472454","y":2014,"court":"M.D. Fla. Oct. 22","by":{"0":"35"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"op":1,"ar":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"0":"1, 29","1":"4","3":"6"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"15, 36, 37, 38","3":"20, 21, 22"}},{"t":"const","label":"Amendment XIV","clauses":[["due-process-14","Due Process Clause (Fourteenth Amendment)"]],"by":{"0":"39"}},{"t":"usc","label":"6 U.S.C. § 482","url":"https://www.law.cornell.edu/uscode/text/6/482","subs":["(b)(3)(A)"],"by":{"0":"19"}},{"t":"usc","label":"10 U.S.C. § 923","url":"https://www.law.cornell.edu/uscode/text/10/923","subs":["(a)(1)","(a)(2)"],"stext":{"head":"§923. Art. 123. Offenses concerning Government computers","paras":[[0,"(a) In General.—Any person subject to this chapter who—"],[1,"(1) knowingly accesses a Government computer, with an unauthorized purpose, and by doing so obtains classified information, with reason to believe such information could be used to the injury of the United States, or to the advantage of any foreign nation, and intentionally communicates, delivers, transmits, or causes to be communicated, delivered, or transmitted such information to any person not entitled to receive it;"],[1,"(2) intentionally accesses a Government computer, with an unauthorized purpose, and thereby obtains classified or other protected information from any Government computer; or"],[1,"(3) knowingly causes the transmission of a program, information, code, or command, and as a result of such conduct, intentionally causes damage without authorization to a Government computer;"],[0,"shall be punished as a court-martial may direct."],[0,"(b) Definitions.—In this section:"],[1,"(1) The term \"computer\" has the meaning given that term in section 1030 of title 18."],[1,"(2) The term \"Government computer\" means a computer owned or operated by or on behalf of the United States Government."],[1,"(3) The term \"damage\" has the meaning given that term in section 1030 of title 18."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/10/923?type=usc&year=mostrecent&link-type=html"},"head":"§923. Art. 123. Offenses concerning Government computers","tname":"Armed Forces","by":{"0":"19","3":"11"}},{"t":"usc","label":"17 U.S.C. § 506","url":"https://www.law.cornell.edu/uscode/text/17/506","subs":["(a)(1)","(a)(B)","(a)(C)"],"stext":{"head":"§506. Criminal offenses","paras":[[0,"(a) Criminal Infringement.—"],[1,"(1) In general.—Any person who willfully infringes a copyright shall be punished as provided under section 2319 of title 18, if the infringement was committed—"],[2,"(A) for purposes of commercial advantage or private financial gain;"],[2,"(B) by the reproduction or distribution, including by electronic means, during any 180–day period, of 1 or more copies or phonorecords of 1 or more copyrighted works, which have a total retail value of more than $1,000; or"],[2,"(C) by the distribution of a work being prepared for commercial distribution, by making it available on a computer network accessible to members of the public, if such person knew or should have known that the work was intended for commercial distribution."],[1,"(2) Evidence.—For purposes of this subsection, evidence of reproduction or distribution of a copyrighted work, by itself, shall not be sufficient to establish willful infringement of a copyright."],[1,"(3) Definition.—In this subsection, the term \"work being prepared for commercial distribution\" means—"],[2,"(A) a computer program, a musical work, a motion picture or other audiovisual work, or a sound recording, if, at the time of unauthorized distribution—"],[3,"(i) the copyright owner has a reasonable expectation of commercial distribution; and"],[3,"(ii) the copies or phonorecords of the work have not been commercially distributed; or"],[2,"(B) a motion picture, if, at the time of unauthorized distribution, the motion picture—"],[3,"(i) has been made available for viewing in a motion picture exhibition facility; and"],[3,"(ii) has not been made available in copies for sale to the general public in the United States in a format intended to permit viewing outside a motion picture exhibition facility."],[0,"(b) Forfeiture, Destruction, and Restitution.—Forfeiture, destruction, and restitution relating to this section shall be subject to section 2323 of title 18, to the extent provided in that section, in addition to any other similar remedies provided by law."],[0,"(c) Fraudulent Copyright Notice.—Any person who, with fraudulent intent, places on any article a notice of copyright or words of the same purport that such person knows to be false, or who, with fraudulent intent, publicly distributes or imports for public distribution any article bearing such notice or words that such person knows to be false, shall be fined not more than $2,500."],[0,"(d) Fraudulent Removal of Copyright Notice.—Any person who, with fraudulent intent, removes or alters any notice of copyright appearing on a copy of a copyrighted work shall be fined not more than $2,500."],[0,"(e) False Representation.—Any person who knowingly makes a false representation of a material fact in the application for copyright registration provided for by section 409, or in any written statement filed in connection with the application, shall be fined not more than $2,500."],[0,"(f) Rights of Attribution and Integrity.—Nothing in this section applies to infringement of the rights conferred by section 106A(a)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/17/506?type=usc&year=mostrecent&link-type=html"},"head":"§506. Criminal offenses","tname":"Copyrights","by":{"0":"26","1":"12, 12","2":"25"}},{"t":"usc","label":"18 U.S.C. § 1030","url":"https://www.law.cornell.edu/uscode/text/18/1030","subs":["(a)(1)","(a)(2)","(a)(2)(C)","(c)(2)(A)","(c)(2)(B)(i)","(e)(1)","(e)(2)(B)","(e)(6)","(g)","(a)(2)(B)","(a)(5)(A)","(1994)","(a)","(a)(2)(A)","(a)(4)","(a)(5)(1994)","(a)(6)(B)","(a)(7)","(c)(2)(B)","(c)(2)(B)(iii)","(c)(4)(A)(i)(I)","(e)(2)","(e)(5)","(e)(8)","(g)(1994)"],"stext":{"head":"§1030. Fraud and related activity in connection with computers","paras":[[0,"(a) Whoever—"],[1,"(1) having knowingly accessed a computer without authorization or exceeding authorized access, and by means of such conduct having obtained information that has been determined by the United States Government pursuant to an Executive order or statute to require protection against unauthorized disclosure for reasons of national defense or foreign relations, or any restricted data, as defined in paragraph y. of section 11 of the Atomic Energy Act of 1954, with reason to believe that such information so obtained could be used to the injury of the United States, or to the advantage of any foreign nation willfully communicates, delivers, transmits, or causes to be communicated, delivered, or transmitted, or attempts to communicate, deliver, transmit or cause to be communicated, delivered, or transmitted the same to any person not entitled to receive it, or willfully retains the same and fails to deliver it to the officer or employee of the United States entitled to receive it;"],[1,"(2) intentionally accesses a computer without authorization or exceeds authorized access, and thereby obtains—"],[2,"(A) information contained in a financial record of a financial institution, or of a card issuer as defined in section 1602(n) 1 of title 15, or contained in a file of a consumer reporting agency on a consumer, as such terms are defined in the Fair Credit Reporting Act (15 U.S.C. 1681 et seq.);"],[2,"(B) information from any department or agency of the United States; or"],[2,"(C) information from any protected computer;"],[1,"(3) intentionally, without authorization to access any nonpublic computer of a department or agency of the United States, accesses such a computer of that department or agency that is exclusively for the use of the Government of the United States or, in the case of a computer not exclusively for such use, is used by or for the Government of the United States and such conduct affects that use by or for the Government of the United States;"],[1,"(4) knowingly and with intent to defraud, accesses a protected computer without authorization, or exceeds authorized access, and by means of such conduct furthers the intended fraud and obtains anything of value, unless the object of the fraud and the thing obtained consists only of the use of the computer and the value of such use is not more than $5,000 in any 1-year period;"],[1,"(5)(A) knowingly causes the transmission of a program, information, code, or command, and as a result of such conduct, intentionally causes damage without authorization, to a protected computer;"],[1,"(B) intentionally accesses a protected computer without authorization, and as a result of such conduct, recklessly causes damage; or"],[1,"(C) intentionally accesses a protected computer without authorization, and as a result of such conduct, causes damage and loss.2"],[1,"(6) knowingly and with intent to defraud traffics (as defined in section 1029) in any password or similar information through which a computer may be accessed without authorization, if—"],[2,"(A) such trafficking affects interstate or foreign commerce; or"],[2,"(B) such computer is used by or for the Government of the United States; 3"],[1,"(7) with intent to extort from any person any money or other thing of value, transmits in interstate or foreign commerce any communication containing any—"],[2,"(A) threat to cause damage to a protected computer;"],[2,"(B) threat to obtain information from a protected computer without authorization or in excess of authorization or to impair the confidentiality of information obtained from a protected computer without authorization or by exceeding authorized access; or"],[2,"(C) demand or request for money or other thing of value in relation to damage to a protected computer, where such damage was caused to facilitate the extortion;"],[0,"shall be punished as provided in subsection (c) of this section."],[0,"(b) Whoever conspires to commit or attempts to commit an offense under subsection (a) of this section shall be punished as provided in subsection (c) of this section."],[0,"(c) The punishment for an offense under subsection (a) or (b) of this section is—"],[1,"(1)(A) a fine under this title or imprisonment for not more than ten years, or both, in the case of an offense under subsection (a)(1) of this section which does not occur after a conviction for another offense under this section, or an attempt to commit an offense punishable under this subparagraph; and"],[1,"(B) a fine under this title or imprisonment for not more than twenty years, or both, in the case of an offense under subsection (a)(1) of this section which occurs after a conviction for another offense under this section, or an attempt to commit an offense punishable under this subparagraph;"],[1,"(2)(A) except as provided in subparagraph (B), a fine under this title or imprisonment for not more than one year, or both, in the case of an offense under subsection (a)(2), (a)(3), or (a)(6) of this section which does not occur after a conviction for another offense under this section, or an attempt to commit an offense punishable under this subparagraph;"],[1,"(B) a fine under this title or imprisonment for not more than 5 years, or both, in the case of an offense under subsection (a)(2), or an attempt to commit an offense punishable under this subparagraph, if—"],[2,"(i) the offense was committed for purposes of commercial advantage or private financial gain;"],[2,"(ii) the offense was committed in furtherance of any criminal or tortious act in violation of the Constitution or laws of the United States or of any State; or"],[2,"(iii) the value of the information obtained exceeds $5,000; and"],[1,"(C) a fine under this title or imprisonment for not more than ten years, or both, in the case of an offense under subsection (a)(2), (a)(3) or (a)(6) of this section which occurs after a conviction for another offense under this section, or an attempt to commit an offense punishable under this subparagraph;"],[1,"(3)(A) a fine under this title or imprisonment for not more than five years, or both, in the case of an offense under subsection (a)(4) or (a)(7) of this section which does not occur after a conviction for another offense under this section, or an attempt to commit an offense punishable under this subparagraph; and"],[1,"(B) a fine under this title or imprisonment for not more than ten years, or both, in the case of an offense under subsection (a)(4),4 or (a)(7) of this section which occurs after a conviction for another offense under this section, or an attempt to commit an offense punishable under this subparagraph;"],[1,"(4)(A) except as provided in subparagraphs (E) and (F), a fine under this title, imprisonment for not more than 5 years, or both, in the case of—"],[2,"(i) an offense under subsection (a)(5)(B), which does not occur after a conviction for another offense under this section, if the offense caused (or, in the case of an attempted offense, would, if completed, have caused)—"],[3,"(I) loss to 1 or more persons during any 1-year period (and, for purposes of an investigation, prosecution, or other proceeding brought by the United States only, loss resulting from a related course of conduct affecting 1 or more other protected computers) aggregating at least $5,000 in value;"],[3,"(II) the modification or impairment, or potential modification or impairment, of the medical examination, diagnosis, treatment, or care of 1 or more individuals;"],[3,"(III) physical injury to any person;"],[3,"(IV) a threat to public health or safety;"],[3,"(V) damage affecting a computer used by or for an entity of the United States Government in furtherance of the administration of justice, national defense, or national security; or"],[3,"(VI) damage affecting 10 or more protected computers during any 1-year period; or"],[2,"(ii) an attempt to commit an offense punishable under this subparagraph;"],[1,"(B) except as provided in subparagraphs (E) and (F), a fine under this title, imprisonment for not more than 10 years, or both, in the case of—"],[2,"(i) an offense under subsection (a)(5)(A), which does not occur after a conviction for another offense under this section, if the offense caused (or, in the case of an attempted offense, would, if completed, have caused) a harm provided in subclauses (I) through (VI) of subparagraph (A)(i); or"],[2,"(ii) an attempt to commit an offense punishable under this subparagraph;"],[1,"(C) except as provided in subparagraphs (E) and (F), a fine under this title, imprisonment for not more than 20 years, or both, in the case of—"],[2,"(i) an offense or an attempt to commit an offense under subparagraphs (A) or (B) of subsection (a)(5) that occurs after a conviction for another offense under this section; or"],[2,"(ii) an attempt to commit an offense punishable under this subparagraph;"],[1,"(D) a fine under this title, imprisonment for not more than 10 years, or both, in the case of—"],[2,"(i) an offense or an attempt to commit an offense under subsection (a)(5)(C) that occurs after a conviction for another offense under this section; or"],[2,"(ii) an attempt to commit an offense punishable under this subparagraph;"],[1,"(E) if the offender attempts to cause or knowingly or recklessly causes serious bodily injury from conduct in violation of subsection (a)(5)(A), a fine under this title, imprisonment for not more than 20 years, or both;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1030?type=usc&year=mostrecent&link-type=html"},"op":5,"ar":1,"head":"§1030. Fraud and related activity in connection with computers","tname":"Crimes and Criminal Procedure","by":{"0":"passim, 5, passim, 2, 25, 7, 7, 28, 6, 6, passim, 7, 34","1":"3, 12, passim, 10, 8, 11","2":"4, 26, 4, 27, 5, 4, 14, 26, 27, 4, 14, 26, 27, 26, 27, 27, 29, 29, 23, 23, 6, 6, 29, 31, 31, 5, 5, 6, 6, 6, 6, 6, 6, 6, 6, 6, 5, 5, 5, 5, 5","3":"15, 3, 15"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/2190","by":{"0":"5, 21","2":"3","3":"7"}},{"t":"usc","label":"18 U.S.C. § 1343","url":"https://www.law.cornell.edu/uscode/text/18/1343","stext":{"head":"§1343. Fraud by wire, radio, or television","paras":[[0,"Whoever, having devised or intending to devise any scheme or artifice to defraud, or for obtaining money or property by means of false or fraudulent pretenses, representations, or promises, transmits or causes to be transmitted by means of wire, radio, or television communication in interstate or foreign commerce, any writings, signs, signals, pictures, or sounds for the purpose of executing such scheme or artifice, shall be fined under this title or imprisoned not more than 20 years, or both. If the violation occurs in relation to, or involving any benefit authorized, transported, transmitted, transferred, disbursed, or paid in connection with, a presidentially declared major disaster or emergency (as those terms are defined in section 102 of the Robert T. Stafford Disaster Relief and Emergency Assistance Act (42 U.S.C. 5122)), or affects a financial institution, such person shall be fined not more than $1,000,000 or imprisoned not more than 30 years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1343?type=usc&year=mostrecent&link-type=html"},"head":"§1343. Fraud by wire, radio, or television","tname":"Crimes and Criminal Procedure","by":{"0":"12","1":"11","2":"2, 10"}},{"t":"usc","label":"18 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/18/1346","stext":{"head":"§1346. Definition of \"scheme or artifice to defraud\"","paras":[[0,"For the purposes of this chapter, the term \"scheme or artifice to defraud\" includes a scheme or artifice to deprive another of the intangible right of honest services."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1346?type=usc&year=mostrecent&link-type=html"},"head":"§1346. Definition of \"scheme or artifice to defraud\"","tname":"Crimes and Criminal Procedure","by":{"0":"12","2":"2, 10"}},{"t":"usc","label":"18 U.S.C. § 1832","url":"https://www.law.cornell.edu/uscode/text/18/1832","subs":["(a)"],"stext":{"head":"§1832. Theft of trade secrets","paras":[[0,"(a) Whoever, with intent to convert a trade secret, that is related to a product or service used in or intended for use in interstate or foreign commerce, to the economic benefit of anyone other than the owner thereof, and intending or knowing that the offense will, injure any owner of that trade secret, knowingly—"],[1,"(1) steals, or without authorization appropriates, takes, carries away, or conceals, or by fraud, artifice, or deception obtains such information;"],[1,"(2) without authorization copies, duplicates, sketches, draws, photographs, downloads, uploads, alters, destroys, photocopies, replicates, transmits, delivers, sends, mails, communicates, or conveys such information;"],[1,"(3) receives, buys, or possesses such information, knowing the same to have been stolen or appropriated, obtained, or converted without authorization;"],[1,"(4) attempts to commit any offense described in paragraphs (1) through (3); or"],[1,"(5) conspires with one or more other persons to commit any offense described in paragraphs (1) through (3), and one or more of such persons do any act to effect the object of the conspiracy,"],[0,"shall, except as provided in subsection (b), be fined under this title or imprisoned not more than 10 years, or both."],[0,"(b) Any organization that commits any offense described in subsection (a) shall be fined not more than the greater of $5,000,000 or 3 times the value of the stolen trade secret to the organization, including expenses for research and design and other costs of reproducing the trade secret that the organization has thereby avoided."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1832?type=usc&year=mostrecent&link-type=html"},"head":"§1832. Theft of trade secrets","tname":"Crimes and Criminal Procedure","by":{"0":"26, 4","2":"24"}},{"t":"usc","label":"26 U.S.C. § 7212","url":"https://www.law.cornell.edu/uscode/text/26/7212","subs":["(a)"],"by":{"0":"29"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"38 U.S.C. § 5318","url":"https://www.law.cornell.edu/uscode/text/38/5318","subs":["(b)"],"by":{"0":"19"}},{"t":"usc","label":"42 U.S.C. § 1320d-6","url":"https://www.law.cornell.edu/uscode/text/42/1320d-6","subs":["(a)(3)","(a)","(a)(2)"],"stext":{"head":"§1320d–6. Wrongful disclosure of individually identifiable health information","paras":[[0,"(a) Offense"],[0,"A person who knowingly and in violation of this part—"],[1,"(1) uses or causes to be used a unique health identifier;"],[1,"(2) obtains individually identifiable health information relating to an individual; or"],[1,"(3) discloses individually identifiable health information to another person,"],[0,"shall be punished as provided in subsection (b). For purposes of the previous sentence, a person (including an employee or other individual) shall be considered to have obtained or disclosed individually identifiable health information in violation of this part if the information is maintained by a covered entity (as defined in the HIPAA privacy regulation described in section 1320d–9(b)(3) of this title) and the individual obtained or disclosed such information without authorization."],[0,"(b) Penalties"],[0,"A person described in subsection (a) shall—"],[1,"(1) be fined not more than $50,000, imprisoned not more than 1 year, or both;"],[1,"(2) if the offense is committed under false pretenses, be fined not more than $100,000, imprisoned not more than 5 years, or both; and"],[1,"(3) if the offense is committed with intent to sell, transfer, or use individually identifiable health information for commercial advantage, personal gain, or malicious harm, be fined not more than $250,000, imprisoned not more than 10 years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1320d-6?type=usc&year=mostrecent&link-type=html"},"head":"§1320d–6. Wrongful disclosure of individually identifiable health information","tname":"The Public Health and Welfare","by":{"0":"26","2":"25","3":"11"}},{"t":"case","label":"Facebook, Inc. v. Power Ventures, Inc.","cite":"844 F.3d 1058","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/844/1058/","op":1,"ar":7,"by":{"1":"6"}},{"t":"case","label":"HiQ Labs, Inc. v. LinkedIn Corp.","cite":"938 F.3d 985","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/938/985/","by":{"1":"7","2":"37","3":"15"}},{"t":"case","label":"Jones v. United States","cite":"529 U.S. 848","y":2000,"id":"1999/99-5739","sc":1,"sum":"Delivered by Justice Ruth Bader Ginsburg, the Court held that an owner-occupied residence not used for any commercial purpose does not qualify as property \"used in\" commerce or commerce-affecting activity, such that arson of such a dwelling is not subject to federal prosecution under section 844(i).","sumSrc":"Oyez","by":{"1":"4"}},{"t":"case","label":"Leocal v. Ashcroft","cite":"543 U.S. 1","y":2004,"id":"2004/03-583","sc":1,"sum":"The Court held that state DUI offenses, except when involving purposeful intent, are accidental and not crimes of violence under federal law. Le therefore did not commit an aggravated felony for which he could be deported.","sumSrc":"Oyez","by":{"1":"4"}},{"t":"case","label":"QVC, Inc. v. Resultly, LLC","cite":"159 F. Supp. 3d 576","y":2016,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/159/576/","by":{"1":"7","3":"14"}},{"t":"case","label":"Sandvig v. Barr","cite":"2020 U.S. Dist. LEXIS 53631","y":2020,"court":"D.D.C. March 27","by":{"1":"9"}},{"t":"case","label":"United States v. Morrison","cite":"844 F.2d 1057","y":1988,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/844/1057/","by":{"1":"12"}},{"t":"case","label":"iii Cited Authorities Page United States v. Thompson/Center Arms Co.","cite":"504 U.S. 505","y":1992,"id":"1991/91-164","sc":1,"sum":"The judgment is affirmed. 924 F. 2d 1041, affirmed. JUSTICE SOUTER, joined by THE CHIEF JUSTICE and JUSTICE O'CONNOR, concluded that the Contender and conversion kit when packaged together have not been \"made\" into a short-barreled rifle for NFA purposes.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"5"}},{"t":"usc","label":"17 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/17/1201","by":{"1":"11"}},{"t":"usc","label":"18 U.S.C. § 641","url":"https://www.law.cornell.edu/uscode/text/18/641","by":{"1":"12"}},{"t":"usc","label":"18 U.S.C. § 1029","url":"https://www.law.cornell.edu/uscode/text/18/1029","by":{"1":"11"}},{"t":"usc","label":"18 U.S.C. § 1831","url":"https://www.law.cornell.edu/uscode/text/18/1831","by":{"1":"11"}},{"t":"usc","label":"18 U.S.C. § 2701","url":"https://www.law.cornell.edu/uscode/text/18/2701","by":{"1":"11"}},{"t":"case","label":"Babb v. Wilkie","cite":"140 S. Ct. 1168","y":2020,"id":"2019/18-882","sc":1,"sum":"The Court held that the federal-sector provision of the Age Discrimination in Employment Act of 1967 demands that personnel actions be untainted by any consideration of age, but but-for causation is important in determining the appropriate remedy that may be obtained.","sumSrc":"Oyez","by":{"2":"25"}},{"t":"case","label":"Beckles v. United States","cite":"137 S. Ct. 886","y":2017,"id":"2016/15-8544","sc":1,"sum":"The Court held that its holding in Johnson v. US regarding the unconstitutionality of the residual clause in the Armed Criminal Career Act does not apply retroactively to identical language in the Sentencing Guidelines.","sumSrc":"Oyez","by":{"2":"48","3":"22"}},{"t":"case","label":"Coates v. City of Cincinnati","cite":"402 U.S. 611","y":1971,"id":"1970/117","sc":1,"sum":"Cincinnati, Ohio, ordinance making it a criminal offense for \"three or more persons to assemble... on any of the sidewalks... and there conduct themselves in a manner annoying to persons passing by...,\" which has not been narrowed by any construction of the Ohio Supreme Court, held violative on its face of the due process standard of vagueness and the constitutional right of free assembly and association. Pp. …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"48"}},{"t":"case","label":"Connecticut Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"43"}},{"t":"case","label":"County of Washington v. Gunther","cite":"452 U.S. 161","y":1981,"id":"1980/80-429","sc":1,"ar":3,"sum":"The Bennett Amendment does not restrict Title VIH's prohibition of sex-based wage discrimination to claims for equal pay for \"equal work.\" Rather, claims for sex-based wage discrimination can also be brought under Title VII even though no member of the opposite sex holds an equal but higher paying job, provided that the challenged wage rate is not exempted under the Equal Pay Act's affirmative defenses as to wage …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"36, 37"}},{"t":"case","label":"Estate of Cowart v. Nicklos Drilling Co.","cite":"505 U.S. 469","y":1992,"id":"1991/91-17","sc":1,"sum":"Section 33(g)'s forfeiture provision applies to a worker whose employer, at the time the worker settles with a third party, is neither paying compensation to the worker nor subject to an order to pay under the Act. The section's language is plain and cannot support the BRB's interpretation. The normal meaning of entitlement includes a right or benefit for which a person qualifies, regardless of whether the right or …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"Gonzales v. Duenas-Alvarez","cite":"549 U.S. 183","y":2007,"id":"2006/05-1629","sc":1,"sum":"The Court ruled unanimously that aiding and abetting a theft qualifies as a \"theft offense\" for purposes of the Immigration and Nationality Act. The opinion by Justice Stephen Breyer held that the common law had done away with all distinctions between \"principals\" and \"aiders and abettors\" of theft crimes.","sumSrc":"Oyez","by":{"2":"33"}},{"t":"case","label":"Holder v. Humanitarian Law Project","cite":"561 U.S. 1","y":2010,"id":"2009/08-1498","sc":1,"sum":"The Court held that sections of the Antiterrorism and Effective Death Penalty Act were not unconstitutionally vague in a lawsuit that named the Kurdistan Workers Party and Liberation Tigers of Tamil Eelam.","sumSrc":"Oyez","by":{"2":"47"}},{"t":"case","label":"Intel Corp. Inv. Policy Comm. v. Sulyma","cite":"140 S. Ct. 768","y":2020,"id":"2019/18-1116","sc":1,"sum":"The Court held that under the Employee Retirement Income Security Act of 1974 requirement that plaintiffs with “actual knowledge” of an alleged fiduciary breach must file suit within three years of gaining that knowledge, a plaintiff does not necessarily have “actual knowledge” of the information contained in disclosures that he receives but does not read or cannot recall reading.","sumSrc":"Oyez","by":{"2":"44"}},{"t":"case","label":"Kansas v. Garcia","cite":"140 S. Ct. 791","y":2020,"id":"2019/17-834","sc":1,"sum":"A case in which the Court upheld Kansas's prosecution of noncitizens who used stolen social security numbers to gain employment.","sumSrc":"Oyez","by":{"2":"23"}},{"t":"case","label":"Little Sisters of the Poor Saints Peter & Paul Home v. Pennsylvania","cite":"140 S. Ct. 2367","y":2020,"id":"2019/19-431","sc":1,"sum":"The Court held that the federal government acted properly when it added extensive exemptions to regulations requiring employers to include contraceptive coverage in employee health plans.","sumSrc":"Oyez","by":{"2":"44"}},{"t":"case","label":"Los Angeles Police Dep’t v. United Reporting Publ’g Corp.","cite":"528 U.S. 32","y":1999,"id":"1999/98-678","sc":1,"sum":"The Court held that the amended statute was not an abridgment of anyone's right to engage in speech, commercial or otherwise, but simply a law regulating access to information in the hands of law enforcement agencies.","sumSrc":"Oyez","by":{"2":"45"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"2":"20, 25"}},{"t":"case","label":"McFadden v. United States","cite":"576 U.S. 186","y":2015,"id":"2014/14-378","sc":1,"sum":"The Court decided that in order to fulfill the intent element of The Controlled Substance Analogue Enforcement Act of 1986, a person must either know that the substance is a controlled substance or be aware of what the substance is without knowing that it is controlled.","sumSrc":"Oyez","by":{"2":"47"}},{"t":"case","label":"Members of the City Council v. Taxpayers for Vincent","cite":"466 U.S. 789","y":1984,"id":"1983/82-975","sc":1,"sum":"Section 28.04 of the Los Angeles Municipal Code prohibits the posting of signs on public property. Appellee Taxpayers for Vincent, a group of supporters of a candidate for election to the Los Angeles City Council, entered into a contract with appellee Candidates' Outdoor Graphics Service (COGS) to fabricate and post signs with the candidate's name on them. COGS produced cardboard signs and attached them to utility …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"46"}},{"t":"case","label":"Mims v. Arrow Fin. Servs., LLC","cite":"565 U.S. 368","y":2012,"id":"2011/10-1195","sc":1,"sum":"The Court held that the Telephone Consumer Protection Act does not strip federal courts of the ability to hear cases that would normally be brought in state courts.","sumSrc":"Oyez","by":{"2":"30"}},{"t":"case","label":"Musacchio v. United States","cite":"136 S. Ct. 709","y":2016,"id":"2015/14-1095","sc":1,"op":1,"ar":2,"sum":"The Court determined that the law of the case doctrine does not require that the sufficiency of evidence be measured against the elements laid out in the jury instructions when those elements require the government to prove more than the statute requires and the government did not object at trial. The Court also determined that a statute of limitations defense that is not raised at trial is not reviewable on appeal.","sumSrc":"Oyez","by":{"2":"17, 21"}},{"t":"case","label":"Nielsen v. Preap","cite":"139 S. Ct. 954","y":2019,"id":"2018/16-1363","sc":1,"sum":"The Ninth Circuit’s judgments—that respondents, who are deportable for certain specified crimes, are not subject to 8 U. S. C. §1226(c)(2)’s mandatory-detention requirement because they were not arrested by immigration officials as soon as they were released from jail—are reversed, and the cases are remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"20"}},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"sum":"Authored by Justice Clarence Thomas, the Court ruled that because the term \"employees,\" as used Title VII of the Civil Rights Act of 1964, includes former employees, Robinson may sue Shell for its allegedly retaliatory post-employment actions.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"28"}},{"t":"case","label":"Sedima, S. P. R. L. v. Imrex Co.","cite":"473 U.S. 479","y":1985,"id":"1984/84-648","sc":1,"sum":"The Racketeer Influenced and Corrupt Organizations Act (RICO), 18 U. S. C. §§ 1961-1968, which is directed at \"racketeering activity\"defined in § 1961(1) to encompass, inter alia,acts \"indictable\" under specific federal criminal provisions, including mail and wire fraud-provides in § 1964(c) for a private civil action to recover treble damages by any person injured in his business or property \"by reason of a …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"49"}},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"sum":"The Court held that a Tennessee man's conviction of domestic violence under state law also prevented him from legally possessing firearms under federal law.","sumSrc":"Oyez","by":{"2":"15, 45, 48"}},{"t":"case","label":"United States v. Lanier","cite":"520 U.S. 259","y":1997,"id":"1996/95-1717","sc":1,"sum":"Authored by Justice David Souter, the Court ruled that the standard of notice that the Court of Appeals employed was higher than the Constitution requires and too demanding.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"case","label":"United States v. Sineneng-Smith","cite":"140 S. Ct. 1575","y":2020,"id":"2019/19-67","sc":1,"sum":"The Court held that the Ninth Circuit’s decision below was an abuse of discretion because it considered and ruled on an issue not raised by the parties.","sumSrc":"Oyez","by":{"2":"44"}},{"t":"case","label":"United States v. Teague","cite":"646 F.3d 1119","y":2011,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/646/1119/","by":{"2":"40"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"sum":"Held that the statute was not overly broad as written. Justice Scalia noted specifically that offers to engage in illegal transactions are categorically excluded from First Amendment protection, and he characterized the speech of an individual claiming to be in possession of child pornography in this category of unprotected speech.","sumSrc":"Oyez","by":{"2":"45, 47"}},{"t":"case","label":"Village of Hoffman Estates v. The Flipside, Hoffman Estates, Inc.","cite":"455 U.S. 489","y":1982,"id":"1981/80-1681","sc":1,"sum":"The ordinance is not facially overbroad or vague but is reasonably clear in its application to appellee.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"46"}},{"t":"case","label":"Virginia v. Hicks","cite":"539 U.S. 113","y":2003,"id":"2002/02-371","sc":1,"sum":"The Court held that the RRHA's trespass policy is not facially invalid under the First Amendment's overbreadth doctrine.","sumSrc":"Oyez","by":{"2":"45"}},{"t":"case","label":"Williams v. Taylor","cite":"529 U.S. 362","y":2000,"id":"1999/98-8384","sc":1,"sum":"In a judgment announced by Justice John Paul Stevens, the Court, with different majorities of Justices for each holding, held that Williams had been deprived of the constitutional right to the effective assistance of counsel and that the Virginia Supreme Court's refusal to set aside the Williams death sentence was a decision that was contrary to or involved an unreasonable application of clearly established federal law, as determined by the Court.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"const","label":"Amendment V","clauses":[["due-process-5","Due Process Clause (Fifth Amendment)"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"2":"46"}},{"t":"law","label":"Pub. L. No. 103-322","url":"https://www.govinfo.gov/link/statute/108/2097","by":{"2":"5"}},{"t":"law","label":"Pub. L. No. 99-474","url":"https://www.govinfo.gov/link/statute/100/1213","by":{"2":"4","3":"passim"}},{"t":"law","label":"Pub. L. No. 110-326","url":"https://www.govinfo.gov/link/plaw/110/public/326","by":{"2":"6"}},{"t":"usc","label":"18 U.S.C. § 1349","url":"https://www.law.cornell.edu/uscode/text/18/1349","by":{"2":"2, 10"}},{"t":"usc","label":"18 U.S.C. § 1839","url":"https://www.law.cornell.edu/uscode/text/18/1839","subs":["(3)"],"by":{"2":"25"}},{"t":"case","label":"Carter v. United States","cite":"530 U.S. 255","y":2000,"id":"1999/99-5716","sc":1,"op":1,"sum":"The Court held that federal bank larceny is not a \"lesser included offense\" of federal bank robbery. The \"[p]etitioner is accordingly prohibited as a matter of law from obtaining a lesser included offense instruction,\" wrote Justice Thomas for the Court.","sumSrc":"Oyez","by":{"3":"9"}},{"t":"case","label":"Davis v. USA Nutra Labs","cite":"303 F. Supp. 3d 1183","y":2018,"court":"D.N.M.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/303/1183/","by":{"3":"17"}},{"t":"case","label":"EF Cultural Travel BV v. Zefer Corp.","cite":"318 F.3d 58","y":2003,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/318/58/","by":{"3":"14"}},{"t":"case","label":"Elonis v. United States","cite":"135 S. Ct. 2001","y":2015,"id":"2014/13-983","sc":1,"sum":"The Court found that in order to violate the transmission of threats provision, the threat requires both an objective and subjective intent.","sumSrc":"Oyez","by":{"3":"22"}},{"t":"case","label":"Evans v. United States","cite":"504 U.S. 255","y":1992,"id":"1991/90-6105","sc":1,"sum":"An affirmative act of inducement by a public official, such as a demand, is not an element of the offense of extortion \"under color of official right\" prohibited by the Hobbs Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"9"}},{"t":"case","label":"Hancock v. AT&T","cite":"701 F.3d 1248","y":2012,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/701/1248/","by":{"3":"17"}},{"t":"case","label":"Melo v. Zumper, Inc.","cite":"439 F. Supp. 3d 683","y":2020,"court":"E.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/439/683/","by":{"3":"17"}},{"t":"case","label":"Meyer v. Uber Techs., Inc.","cite":"868 F.3d 66","y":2017,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/868/66/","by":{"3":"17"}},{"t":"case","label":"Missouri v. Frye","cite":"566 U.S. 134","y":2012,"id":"2011/10-444","sc":1,"sum":"The Court held that the Sixth Amendment requires defense attorneys to communicate formal plea offers from the prosecution.","sumSrc":"Oyez","by":{"3":"14"}},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"sum":"1. A criminal intent is an essential element of an offense under 18 U. S. C. § 641, which provides that \"whoever embezzles, steals, purloins, or knowingly converts\" property -of the United States is punishable by fine and imprisonment.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"9"}},{"t":"case","label":"NLRB v. Catholic Bishop of Chicago","cite":"440 U.S. 490","y":1978,"id":"1978/77-752","sc":1,"sum":"Schools operated by a church to teach both religious and secular subjects are not within the jurisdiction granted by the National Labor Relations Act, and the NLRB was therefore without authority to issue the orders against respondents.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"20"}},{"t":"case","label":"NLRB v. SW General, Inc.","cite":"137 S. Ct. 929","y":2017,"id":"2016/15-1251","sc":1,"sum":"The Court determined that the limitations on nominees to vacant positions serving in an acting capacity under the Federal Vacancies Reform Act apply equally to first assistants who take on the position and to those who are selected by the President from within the same agency or from another agency.","sumSrc":"Oyez","by":{"3":"9"}},{"t":"case","label":"Riley v. California","cite":"573 U.S. 373","y":2014,"id":"2013/13-132","sc":1,"sum":"The Court found that the San Diego Police Department's search of an arrested gang member's cell phone pictures without a warrant violated the Fourth Amendment.","sumSrc":"Oyez","by":{"3":"12"}},{"t":"case","label":"Royal Truck & Tractor Sales Servs. Inc. v. Kraft, ___ F.3d ___","cite":"2020 WL 5406118","y":2020,"court":"6th Cir.","op":4,"by":{"3":"18"}},{"t":"case","label":"iv Sw. Airlines Co. v. Farechase, Inc.","cite":"318 F. Supp. 2d 435","y":2004,"court":"N.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/318/435/","by":{"3":"15"}},{"t":"case","label":"United States v. Aguilar","cite":"515 U.S. 593","y":1995,"id":"1994/94-270","sc":1,"sum":"The Supreme Court held that making false statements to an FBI agent who may or may not testify at trial is not sufficient to support a conviction for obstruction of justice. Aguilar’s conviction for disclosing a wiretap was proper, however, because the statute does not require that the wiretap is currently in force. The First Amendment did not require excluding expired wiretaps from the statute either.","sumSrc":"Oyez","by":{"3":"6"}},{"t":"case","label":"United States v. Auernheimer","cite":"748 F.3d 525","y":2014,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/748/525/","by":{"3":"14"}},{"t":"case","label":"United States v. Markiewicz","cite":"978 F.2d 786","y":1992,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/978/786/","by":{"3":"2"}},{"t":"usc","label":"18 U.S.C. § 1163","url":"https://www.law.cornell.edu/uscode/text/18/1163","stext":{"head":"§1163. Embezzlement and theft from Indian tribal organizations","paras":[[0,"Whoever embezzles, steals, knowingly converts to his use or the use of another, willfully misapplies, or willfully permits to be misapplied, any of the moneys, funds, credits, goods, assets, or other property belonging to any Indian tribal organization or intrusted to the custody or care of any officer, employee, or agent of an Indian tribal organization; or"],[0,"Whoever, knowing any such moneys, funds, credits, goods, assets, or other property to have been so embezzled, stolen, converted, misapplied or permitted to be misapplied, receives, conceals, or retains the same with intent to convert it to his use or the use of another—"],[0,"Shall be fined under this title, or imprisoned not more than five years, or both; but if the value of such property does not exceed the sum of $1,000, he shall be fined under this title, or imprisoned not more than one year, or both."],[0,"As used in this section, the term \"Indian tribal organization\" means any tribe, band, or community of Indians which is subject to the laws of the United States relating to Indian affairs or any corporation, association, or group which is organized under any of such laws."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1163?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1163. Embezzlement and theft from Indian tribal organizations","tname":"Crimes and Criminal Procedure","by":{"3":"2"}},{"t":"usc","label":"18 U.S.C. § 2261A","url":"https://www.law.cornell.edu/uscode/text/18/2261A","subs":["(2)"],"by":{"3":"11"}},{"t":"law","label":"Freedom of Information Act, Pub. L. No. 89-487","url":"https://www.govinfo.gov/link/statute/80/250","by":{"3":"3"}}]};